examples.code:
variable "TAG" { default = "dev" }
group "default" { targets = ["api", "worker"] }
target "api" {
  context    = "."
  dockerfile = "Dockerfile"
  target     = "api"
  tags       = ["ghcr.io/nicocano/api:${TAG}"]
  platforms  = ["linux/amd64", "linux/arm64"]
}
target "worker" {
  inherits = ["api"]
  target   = "worker"
  tags     = ["ghcr.io/nicocano/worker:${TAG}"]
}
